style.css:
@-moz-document domain("pekora.zip"), domain("www.pekora.zip") {
/* === 1. Remove current play button image/icon styles === */
.play-button,
a.play-button,
button.play,
.play-icon {
  background: none !important;
  background-image: none !important;
  mask: none !important;
  -webkit-mask: none !important;
  color: inherit !important;
}

/* === 2. Add classic triangle "▶" as content === */
.play-button::before,
a.play-button::before,
button.play::before,
.play-icon::before {
  content: "▶";
  font-size: 1.5em;
  color: white;
  margin-right: 6px;
  display: inline-block;
  vertical-align: middle;
}

/* === 3. Optional: Add hover or pressed styles === */
.play-button:hover::before,
a.play-button:hover::before,
button.play:hover::before {
  color: #ffcc00; /* a retro highlight color */
}
}
